public class InnerKnowledgeBaseRedshiftConfigurationFactory(Action<Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftConfiguration>
{

    internal InnerKnowledgeBaseRedshiftQueryEngineConfigurationFactory QueryEngineConfigurationFactory { get; set; }

    internal InnerKnowledgeBaseQueryGenerationConfigurationFactory QueryGenerationConfigurationFactory { get; set; }

    protected override Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftConfiguration Create()
    {
        var redshiftConfigurationResult = CreateRedshiftConfiguration();
        factoryAction?.Invoke(redshiftConfigurationResult);

        return redshiftConfigurationResult;
    }

    private Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftConfiguration CreateRedshiftConfiguration()
    {
        var redshiftConfigurationResult = new Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftConfiguration();

        return redshiftConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftConfiguration result)
    {
        base.CreateChildren(result);

        result.QueryEngineConfiguration ??= QueryEngineConfigurationFactory?.Build();
        result.QueryGenerationConfiguration ??= QueryGenerationConfigurationFactory?.Build();
    }

} // End Of Class

